function EquipUtils.SortEquipBackpackData(equipBackpackData, sortType, asc)
    equipBackpackData = checkTable(equipBackpackData)
    sortType = checkNumber(sortType)
    asc = checkBool(asc)

    local t = clone(equipBackpackData)
    for i, v in ipairs(t) do
        v.isEquip = checkInt(v.playerCardId) > 0 and 1 or 0
        v.isEngrave = checkInt(v.bindPlayerCardId) > 0 and 1 or 0
    end
    local fieldNames
    if sortType == Constants.SortType.Quality then
        fieldNames = {"isEquip", "locked",  "quality", "isEngrave", 'star', "level", "suitId", "part", "refId", "id"}
    elseif sortType == Constants.SortType.Level then
        fieldNames = {"isEquip", "locked", "isEngrave", "level", "quality", "star", "suitId", "part", "refId", "id"}
    end

    if fieldNames then
        ---装备稀有度排序
        table.sort(t, function(a, b)
            return CommonChecker(a, b, fieldNames, asc, {
                ["suitId"] = false,
                ["part"]   = false,
                ["isEquip"]   = false,
            })
        end)
    end

    return t
end

function EquipUtils.SortEquipCultivateBackpackData(equipBackpackData, sortType, asc, extraParams)
    equipBackpackData = checkTable(equipBackpackData)
    sortType = checkNumber(sortType)
    asc = checkBool(asc)
    local part = 0
    local selectFoods = {}
    if extraParams then
        part = checkNumber(extraParams.part)
        selectFoods = extraParams.selectFoods or {}
    end
    local t = clone(equipBackpackData)
    table.walk(t, function(i, data)
        local refId = data.refId
        local idFlag = string.format("%s_%s", refId, data.id)
        data.selectFoodPriority = selectFoods[idFlag] and 2 or 1
        local isIdentical = data.part == part
        data.identicalPriority = isIdentical and 2 or 1
        data.isEquip = checkInt(data.playerCardId) > 0 and 2 or 1
        data.isEngrave = checkInt(data.bindPlayerCardId) > 0 and 2 or 1
    end)

    --- 同部位》核心》其他部位
    local fieldNames
    if sortType == Constants.SortType.Quality then
        ---装备稀有度排序
        fieldNames = {"isEquip", "locked", "selectFoodPriority", "identicalPriority", "isEngrave", "quality", "star", "level", "suitId", "part", "refId", "id"}
    elseif sortType == Constants.SortType.Level then
        ---装备等级排序
        fieldNames = {"isEquip", "locked", "selectFoodPriority", "identicalPriority", "isEngrave", "star", "level", "quality", "star", "suitId", "part", "refId", "id"}
    end
    table.sort(t, function(a, b)
        return CommonChecker(a, b, fieldNames, asc, {
            ["selectFoodPriority"] = true,
            ["identicalPriority"] = true,
            ["suitId"] = false,
            ["part"] = false,
        })
    end)

    return t
end

function EquipUtils.SortEquipReclaimBackpackData(equipBackpackData, sortType, asc)
    equipBackpackData = checkTable(equipBackpackData)
    sortType = checkNumber(sortType)
    asc = checkBool(asc)

    local fieldNames
    if sortType == Constants.SortType.Quality then
        fieldNames = {"quality", "part", "level", "goodsId", "id"}
    elseif sortType == Constants.SortType.Level then
        fieldNames = {"level",   "part", "quality", "goodsId", "id"}
    end

    if fieldNames then
        ---装备稀有度排序
        table.sort(equipBackpackData, function(a, b)
            return CommonChecker(a, b, fieldNames, asc, {
                ["part"]   = false,
            })
        end)
    end

    return equipBackpackData
end


function EquipUtils.ScreenEquip(data, screenDic, extraParams)
    data      = checkTable(data)
    screenDic = checkTable(screenDic)
    
    -- print("EquipUtils.ScreenEquip---->>>", table.toString(screenDic))
    local CheckQuality   = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Quality,  Constants.EquipFilterType.Quality,  screenDic, extraParams)
    local CheckStar   = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Star,  Constants.EquipFilterType.Star,  screenDic, extraParams)
    local CheckMainAttr  = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.MainAttr, Constants.EquipFilterType.MainAttr, screenDic, extraParams)
    local CheckOtherType = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Other,    Constants.EquipFilterType.Other,    screenDic, extraParams)
    local CheckPart = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Part,    Constants.EquipFilterType.Part,    screenDic, extraParams)
    --local CheckSubAttrQuality = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.SubAttrQuality,    Constants.EquipFilterType.SubAttrQuality,    screenDic, extraParams)
    --local CheckSubAttr = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.SubAttr,    Constants.EquipFilterType.SubAttr,    screenDic, extraParams)
    local CheckSubAttr = EquipUtils.AnalyzeScreenDictSubAttr(screenDic)

    local list = {}
    for i, v in pairs(data) do
        local isCanIns = CheckQuality(v) and CheckMainAttr(v) and CheckStar(v) and CheckOtherType(v) and CheckPart(v) and CheckSubAttr(v)
        if isCanIns then
            table.insert(list, v)
        end
    end

    return list
end

--- AnalyzeScreenDict
--- 涂鸦回收数据结构不支持
---@param screenClass Constants.EquipScreenClass
---@param filterType Constants.EquipFilterType | Constants.EquipCultivateFastSelectFilterType | Constants.EquipCultivateFilterType 
---@param screenDict table
---@param extraParams table
function EquipUtils.AnalyzeScreenDict(screenClass, filterType, screenDict, extraParams)
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    if screenClass == Constants.EquipScreenClass.Quality then
        local qualityScreenClassDic = screenDict[filterType]
        ---@field qualityMap table<number, number> 
        local qualityMap = {}
        if qualityScreenClassDic then
            for i, v in pairs(qualityScreenClassDic) do
                qualityMap[v] = v
            end
        end
        --- 是否全选品质
        local isAllSelectQuality = next(qualityMap) == nil
        local function CheckQuality(data)
            return isAllSelectQuality or qualityMap[checkNumber(data.quality)] ~= nil
        end

        return CheckQuality
    elseif screenClass == Constants.EquipScreenClass.Part then
        local partScreenClassDic = screenDict[filterType]
        local parts = {}
        if partScreenClassDic then
            for i, v in pairs(partScreenClassDic) do
                parts[v] = v
            end
        end
        --- 是否全选
        local isAllSelectPart = next(parts) == nil
        local function CheckPart(data)
            if isAllSelectPart then
                return true
            end
            return parts[checkNumber(data.part)] ~= nil
        end

        return CheckPart
    elseif screenClass == Constants.EquipScreenClass.Other then

        local career = 0
        if extraParams then
            career = checkNumber(extraParams.career)
        end
        local otherScreenClassDic = screenDict[filterType]
        local otherMap = {}
        if otherScreenClassDic then
            for i, v in pairs(otherScreenClassDic) do
                otherMap[v] = v
            end
        end
        local EquipFilterOtherType = Constants.EquipFilterOtherType
        local filterConditionConf = {
            [EquipFilterOtherType.CareerMismatch] = function(v)
                local occupationId = checkNumber(v.occupationId)
                return career > 0 and occupationId > 0 and occupationId ~= career
            end,
            [EquipFilterOtherType.Equipped] = function(v)
                return false
                --return checkNumber(v.playerCardId) > 0
            end
        }

        local function CheckOtherType(data)
            local isCanIns = true
            for otherTypeName, otherType in pairs(EquipFilterOtherType) do
                local isTick = otherMap[otherType] ~= nil
                local result = filterConditionConf[otherType](data)
                if isTick then
                    isCanIns = isCanIns or result
                else
                    isCanIns = isCanIns and not result
                end

            end
            return isCanIns
        end

        return CheckOtherType

    elseif screenClass == Constants.EquipScreenClass.MainAttr then
        local mainAttrScreenClassDic = screenDict[filterType]
        ---@field qualityMap table<number, number> 
        local mainAttrMap = {}
        if mainAttrScreenClassDic then
            for i, v in pairs(mainAttrScreenClassDic) do
                mainAttrMap[v] = v
            end
        end
        local isAllSelectMainAttr = next(mainAttrMap) == nil
        local function CheckMainAttr(data)
            return isAllSelectMainAttr or mainAttrMap[checkNumber(data.mainAttrId)] ~= nil
        end
        return CheckMainAttr
    elseif screenClass == Constants.EquipScreenClass.Star then
        local starScreenClassDic = screenDict[filterType]
        ---@field starMap table<number, number>
        local starMap = {}
        if starScreenClassDic then
            for i, v in pairs(starScreenClassDic) do
                starMap[v] = v
            end
        end
        --- 是否全选品质
        local isAllSelectQuality = next(starMap) == nil
        local function CheckStar(data)
            return isAllSelectQuality or starMap[checkNumber(data.star)] ~= nil
        end

        return CheckStar
    elseif screenClass == Constants.EquipScreenClass.SubAttrQuality then
        local starScreenClassDic = screenDict[filterType]
        local subAttr = {}
        if starScreenClassDic then
            for i, v in pairs(starScreenClassDic) do
                subAttr[v] = v
            end
        end
        --- 是否全选品质
        local isAllSelectQuality = next(subAttr) == nil
        local function CheckSubAttrQuality(data)
            if isAllSelectQuality then
                return true
            end 
            local equipDojo = equipComp:GetEquipById(data.id)
            for i = 1, 5 do
                if subAttr[checkNumber(equipDojo[string.format('attr%dQuality', i)])] then
                    return true
                end
            end
            return false
        end

        return CheckSubAttrQuality
    elseif screenClass == Constants.EquipScreenClass.SubAttr then
        local starScreenClassDic = screenDict[filterType]
        local subAttr = {}
        if starScreenClassDic then
            for i, v in pairs(starScreenClassDic) do
                subAttr[v] = v
            end
        end
        --- 是否全选
        local isAllSelectQuality = next(subAttr) == nil
        local function CheckSubAttr(data)
            if isAllSelectQuality then
                return true
            end
            local equipDojo = equipComp:GetEquipById(data.id)
            for i = 1, 5 do
                if subAttr[checkNumber(equipDojo[string.format('attr%dId', i)])] then
                    return true
                end
            end
            return false
        end

        return CheckSubAttr
    end
end

function EquipUtils.AnalyzeScreenDictSubAttr(screenDict)
    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local attrDict = screenDict[Constants.EquipFilterType.SubAttr]
    local attr = {}
    if attrDict then
        for i, v in pairs(attrDict) do
            attr[v] = v
        end
    end
    local isAllAttr = next(attr) == nil

    local attrQualityDict = screenDict[Constants.EquipFilterType.SubAttrQuality]
    local attrQuality = {}
    if attrQualityDict then
        for i, v in pairs(attrQualityDict) do
            attrQuality[v] = v
        end
    end
    local isAllAttrQuality = next(attrQuality) == nil
    
    local function CheckSubAttr(data)
        local equipDojo = equipComp:GetEquipById(data.id)
        if not isAllAttrQuality then
            for i = 1, 5 do
                if attrQuality[checkNumber(equipDojo[string.format('attr%dQuality', i)])] then
                    if not isAllAttr then
                        if attr[checkNumber(equipDojo[string.format('attr%dId', i)])] then
                            return true
                        end
                    else
                        return true
                    end
                end
            end
        else
            if not isAllAttr then
                for i = 1, 5 do
                    if attr[checkNumber(equipDojo[string.format('attr%dId', i)])] then
                        return true
                    end
                end
            else
                return true
            end
        end
        return false
    end
    return CheckSubAttr
end


