function EquipUtils.ScreenEquipCultivate(data, screenDic, extraParams, filterClass)
    local UIFilterType                       = Constants.UIFilterType
    local EquipCultivateFastSelectFilterType = Constants.EquipCultivateFastSelectFilterType
    local EquipCultivateFilterType           = Constants.EquipCultivateFilterType
    
    local QualityFilterType                  = filterClass == UIFilterType.EquipCultivate and EquipCultivateFilterType.Quality or EquipCultivateFastSelectFilterType.Quality
    local CheckQuality = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Quality, QualityFilterType, screenDic, extraParams)
    -- list = ScreenEquipCultivateByType(data, QualityFilterType, screenDic)

    local PartFilterType = filterClass == UIFilterType.EquipCultivate and EquipCultivateFilterType.Part or EquipCultivateFastSelectFilterType.Part
    local CheckPart = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.Part, PartFilterType, screenDic, extraParams)

    local MainAttrType = filterClass == UIFilterType.EquipCultivate and EquipCultivateFilterType.MainAttr or EquipCultivateFastSelectFilterType.MainAttr
    local CheckMainAttr = EquipUtils.AnalyzeScreenDict(Constants.EquipScreenClass.MainAttr, MainAttrType, screenDic, extraParams)

    -- list = ScreenEquipCultivateByType(list, PartFilterType, screenDic, extraParams)

    local list = {}
    for i, v in pairs(data) do
        local isCanIns = CheckQuality(v) and CheckPart(v) and CheckMainAttr(v)
        if isCanIns then
            table.insert(list, v)
        end
    end

    return list
end


