---GetEquipSuitDesc
---@param suitId number
---@param color table
function EquipUtils.GetEquipSuitDesc(suitId, color)
    local suitBaseData = cardConfMgr:GetEquipSuitBaseData(suitId)
    local effectNums = suitBaseData.effectNums

    local descList = {}
    for i, effectNum in ipairs(effectNums) do
        local key = EquipUtils.GetEquipCoreMainId(suitId, effectNum)
        ---@type EquipCoreEffectVo
        local equipSuitVo = cardConfMgr:GetEquipSuitVoById(key)
        table.insert(descList, localize("[_num_件效果]\n", {_num_ = effectNum}))
        table.insert(descList, equipSuitVo.desc)
        table.insert(descList, "\n")
    end

    return table.concat(descList)
end

---GetUnlockAttrLvList
---获取基础属性个数
---@param equipDojo EquipDojo
---@param equipVo EquipVo  可选
---@param equipQualityVo EquipQualityVo  可选
---@return number 基础属性个数
function EquipUtils.GetBaseAttrCount(equipDojo, equipVo, equipQualityVo)
    if equipVo == nil then
        ---@type EquipVo
        equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    end
    if equipQualityVo == nil then
        ---@type EquipQualityVo
        equipQualityVo = cardConfMgr:GetEquipQualityVoByRefId(equipVo.rare)
    end
    local maxNum = equipQualityVo.maxNum
    local baseAttrCount = 0
    local level = checkNumber(equipDojo.level)
    local overMax = equipQualityVo.overMax
    local baseLv = equipQualityVo.baseLv
    for i = 1, maxNum do
        local attrAdditionId = checkNumber(equipDojo[string.format("attr%sId", i)])
        if attrAdditionId > 0 and level < (baseLv + overMax * i) then
            baseAttrCount = baseAttrCount + 1
        end
    end
    return baseAttrCount
end

---GetEquipCoreRareColor
---获取装备稀有度颜色
---@param rare Constants.QualityType
function EquipUtils.GetEquipCoreRareColor(rare)
    local color
    rare = checkNumber(rare)
    if rare <= 0 then
        color = "#dedede"
    else
        local QualityType = Constants.QualityType
        local colors = {
            [QualityType.Whit] = "#b3b3b3",
            [QualityType.Green] = "#3bb128",
            [QualityType.Blue] = "#3d97e3",
            [QualityType.Purple] = "#dd3bec",
            [QualityType.Orange] = "#ffb400",
        }
        color = colors[rare] or "#dedede"
    end

    return XLuaUtils.HexToColor(color)
end

