---GetActiveSuitEffectList
---@param equipmentCoreId number 装备核心配表id
---@param suits table<number, number> <suitId, suitPartCount>
function EquipUtils.GetActiveSuitEffectList(equipmentCoreId, suits)
    local suitList = {}
    if checkNumber(equipmentCoreId) <= 0 then
        return suitList
    end
    ---@type EquipCoreVo
    local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreId)
    local suitId = equipCoreVo.suitId
    ---@type EquipCoreEffectVo[]
    local equipCoreEffectVos = cardConfMgr:GetAllEquipCoreEffectByRefId(equipmentCoreId)

    local suitPartCount = checkNumber(suits[tostring(suitId)])
    for i, equipCoreEffectVo in ipairs(equipCoreEffectVos) do
        local suitNum = equipCoreEffectVo.suitNum
        if suitPartCount >= suitNum then
            table.insert(suitList, {
                --coreId = equipmentCoreId,
                suitId = suitId,
                effectNum = suitNum,
                --desc = equipCoreEffectVo.desc,
                --partCount = suitPartCount,
                --occupationId = equipCoreEffectVo.occupationId
            })
        end
    end

    return suitList
end

---GetEquipCoreSuitDesc
---@param equipmentCoreId number 装备核心配表id
function EquipUtils.GetEquipCoreSuitDesc(equipmentCoreId)
    local suitEffectList = EquipUtils.GetAllSuitEffectList(equipmentCoreId, {})
    -- colorList = colorList or {}
    local descList = {}
    for _, suitData in ipairs(suitEffectList) do
        table.insert(descList, string.format("<color=#ffffff>"))
