        table.insert(descList, "\n")
        --table.insert(descList, "\n")
    end

    return table.concat(descList)
end

---GetAllSuitEffectList
---@param equipmentCoreId number 装备核心配表id
---@param suits table<number, number> <suitId, suitPartCount>
function EquipUtils.GetAllSuitEffectList(equipmentCoreId, suits)
    ---@type EquipCoreVo
    local equipCoreVo = cardConfMgr:GetEquipCoreVoById(equipmentCoreId)
    local suitId = equipCoreVo.suitId
    local occupationId = equipCoreVo.occupationId
    local partCount = checkNumber(suits[tostring(suitId)])

    --- 一个核心 对应 一组 套装
    ---@type EquipCoreEffectVo[]
    local equipCoreEffectVos = cardConfMgr:GetAllEquipCoreEffectByRefId(equipmentCoreId)
    local suitList = {}
    local lastActiveIndex
    for i, equipCoreEffectVo in ipairs(equipCoreEffectVos) do

        local effectNum = equipCoreEffectVo.suitNum
        local isActive = partCount >= effectNum
        table.insert(suitList, {
            occupationId = occupationId,
            effectNum = effectNum,
            desc = equipCoreEffectVo.desc,
            activation = isActive and 1 or 0,
        })
        if isActive then
            lastActiveIndex = i
        end
    end
    if lastActiveIndex then
        suitList[lastActiveIndex].lastActiveIndex = lastActiveIndex
    end

    return suitList, lastActiveIndex
end

---CheckCoreIsUnLock
---检查核心是否解锁
---@param equipmentCoreId number 核心配表id
---@param partCount number       套装散件个数
function EquipUtils.CheckCoreIsUnLock(equipmentCoreId, partCount)
    ---@type EquipCoreEffectVo[]
    local equipCoreEffectVos = cardConfMgr:GetAllEquipCoreEffectByRefId(equipmentCoreId)
    ---@param v EquipCoreEffectVo
    for i, v in ipairs(equipCoreEffectVos) do
        if partCount >= v.suitNum then
            return true
        end
    end
    return false
end

