---GetFirstEquipId
---@param equipIdList table<number,number> <part, playerEquipId>
function EquipUtils.GetFirstEquipId(equipIdList)
    equipIdList = equipIdList or {}
    local id = 0
    for i, playerEquipId in pairs(equipIdList) do
        if checkNumber(playerEquipId) > 0 then
            id = checkNumber(playerEquipId)
            break
        end
    end
    return id
end

---CheckIsInstallEquip
---@param equipIdList table<number,number> <part, playerEquipId>
function EquipUtils.CheckIsInstallEquip(equipIdList)
    return EquipUtils.GetFirstEquipId(equipIdList) > 0
end

