---CheckIsOwnEquipByCardDojo
---@param cardDojo CardDojo
function EquipUtils.CheckIsOwnEquipByCardDojo(cardDojo)

    local CheckData = function(field)
        if isTable(field) then
            if next(field) ~= nil then
                return true
            end
        else
            if checkNumber(field) > 0 then
                return true
            end
        end
        return false
    end

    local equipmentCore = cardDojo.equipmentCore
    if CheckData(equipmentCore) then
        return true
    end

    local GetEquipIdKeyByPart = EquipUtils.GetEquipIdKeyByPart
    for i = 1, Constants.CardEquipmentNo do
        local key = GetEquipIdKeyByPart(i)
        local data = cardDojo[key]
        if CheckData(data) then
            return true
        end
    end
    return false
end

---GetEquipSuitInfoByEquipDojoList
---根据装备id列表获取装备套装信息 id, partCount
---@param equipDojoList table<number, EquipDojo> 装备数据列表
---@param minOwnCount number 最小套装散件拥有数量
---@return table table<number,number> <suitId, partCount>
function EquipUtils.GetEquipSuitInfoByEquipDojoList(equipDojoList, minOwnCount)
    local count = 0
    for i, equipDojo in pairs(equipDojoList) do
        if equipDojo and next(equipDojo) ~= nil then
            count = count + 1
        end
    end
    local suits = {}
    local suitEquipMaxRares = {}
    minOwnCount = minOwnCount or 1
    if count < minOwnCount then
        return suits, suitEquipMaxRares
    end

    for _, equipDojo in pairs(equipDojoList) do
        if equipDojo and next(equipDojo) and checkNumber(equipDojo.equipmentId) > 0 then
            local vo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
            local suitId = checkNumber(vo.suitId)
            if suitId > 0 then
                if suits[tostring(suitId)] ~= nil then
                    suits[tostring(suitId)] = suits[tostring(suitId)] + 1
                    local oldRare = suitEquipMaxRares[tostring(suitId)]
                    suitEquipMaxRares[tostring(suitId)] = math.max(oldRare, checkNumber(vo.rare))
                else
                    suits[tostring(suitId)] = 1
                    suitEquipMaxRares[tostring(suitId)] = checkNumber(vo.rare)
                end
            end
        end
    end
    return suits, suitEquipMaxRares
end

---进入装备养成界面
---@param equipDojo EquipDojo
function EquipUtils.EnterCultivateEquipDialog(equipDojo)
    if EquipUtils.IsCanLadderRise(equipDojo) then
        -- 升阶
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateOverseaEquipmentLadderRiseDialog,
                              parameters = {
                                  equipDojo = equipDojo
                              }
        })
    elseif EquipUtils.IsCanLadderRiseUpgrade(equipDojo) then
        -- 升阶强化
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateOverseaEquipmentLadderUpgradeDialog,
            parameters = {
                equipDojo = equipDojo
            }
        })
    elseif EquipUtils.CanEngrave(equipDojo) then
        -- 刻印
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateOverseaEquipEngraveChoosePopup,
                              parameters = {
                                  equipDojo = equipDojo
                              }
        })
    elseif checkInt(equipDojo.level) < CardProgressionConstants.EquipmentLevelUpperLimit then
        -- 升级
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateOverseaEquipmentUpgradeDialog,
                              parameters = {
                                  equipDojo = equipDojo
                              }
        })
    elseif checkInt(equipDojo.star) < EquipUtils.GetEquipmentStarMaxByEquipmentId(equipDojo.equipmentId) then
        -- 升星
        UIModule.OpenDialog({ id = Constants.UITypeIds.CultivateOverseaEquipmentStarRiseDialog,
                              parameters = {
                                  equipDojo = equipDojo
                              }
        })
    end
end

