--- GenerateEquipDataByDojo
--- 通过服务端数据生成装备数据
---@param equipDojo EquipDojo 装备服务端数据
---@param confFieldCache table  装备配表字段缓存
function EquipUtils.GenerateEquipDataByDojo(equipDojo, confFieldCache)
    local goodsId   = equipDojo.equipmentId
    local quality, part, suitId
    if confFieldCache[goodsId] == nil then
        ---@type EquipVo
        local equipVo = cardConfMgr:GetEquipVoById(goodsId)
        quality, part, suitId = equipVo.rare, equipVo.part, equipVo.suitId
        confFieldCache[goodsId] = {quality, part, }
    else
        quality, part, suitId = SafeUnpack(confFieldCache[goodsId])
    end
    return {
        id         = equipDojo.id,
        refId      = goodsId,
        goodsId    = goodsId,
        goodsType  = Constants.IDType.Equipment,
        level      = checkNumber(equipDojo.level),
        suitId     = suitId,
        quality    = quality,
        part       = part,
        mainAttrId = checkNumber(equipDojo.mainAttrId),
        
    }
end

--- GenerateCoreDataByDojo
--- 通过服务端数据生成核心数据
---@param equipmentCoreDojo EquipmentCoreDojo
---@param confFieldCache table  装备配表字段缓存
function EquipUtils.GenerateCoreDataByDojo(equipmentCoreDojo, confFieldCache)
    local goodsId   = equipmentCoreDojo.equipmentCoreId
    local quality, suitId
    if confFieldCache[goodsId] == nil then
        ---@type EquipCoreVo
        local equipCoreVo = cardConfMgr:GetEquipCoreVoById(goodsId)
        suitId = equipCoreVo.suitId
        quality = equipCoreVo.quality
        confFieldCache[goodsId] = {quality, suitId}
    else
        quality, suitId = SafeUnpack(confFieldCache[goodsId])
    end

    -- "quality", "level", "suitId", "part", "refId", "id"
    return {
        id         = equipmentCoreDojo.id,
        refId      = goodsId,
        goodsId    = goodsId,
        goodsType  = Constants.IDType.EquipmentCore,
        level      = 1,
        suitId     = suitId,
        quality    = quality,
        part       = 0,
        mainAttrId = 0,
    }
end

