---通过星级获取最大等级
function EquipUtils.GetMaxLvByStarAndQuality(star, quality)
    ---@type EquipmentCultivateAndReclaimVo[]
    local vos = CfUtils.GetCf(AutoIds.IdSetting3052, "EquipmentCultivateAndReclaimVo", true)
    local maxLv = 0
    for key, vo in pairs(vos) do
        if vo.star == star and vo.quality == quality then
            maxLv = math.max(maxLv, vo.level)
        end
    end
    return maxLv
