--- 获取 红装重铸参数表 对应id数值
---@param paramsId CardProgressionConstants.LadderRiseParams @ 红装重铸参数表id
---@return any
function EquipUtils.GetLadderRiseParamValue(paramId)
    local paramValue = EquipUtils.LadderRiseParamValue[paramId]
    if not paramValue then
        local paramVo = EquipUtils.GetLadderRiseParamVo(paramId)
        local ParamId = CardProgressionConstants.LadderRiseParams
        if paramId == ParamId.StartStar
            or paramId == ParamId.AttrCount
            or paramId == ParamId.UnlockSecondAttrReforgeTimes
            
        then
            paramValue = checkNumber(paramVo.num)
        else
            local temp = parse_strings(paramVo.num, ";")
            paramValue = {}
            for key, value in pairs(temp) do
                table.insert(paramValue, checkNumber(value))
            end
        end
        EquipUtils.LadderRiseParamValue[paramId] = paramValue
    end
    return paramValue
end

---是否能升阶
---@param dojo EquipDojo
---@return boolean 是否能升阶
function EquipUtils.IsCanLadderRise(dojo)
    ---5星5级
    local conditions =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.UnlockCondition)
    local limitStar, limitLv = SafeUnpack(conditions)
    local star = checkNumber(dojo.star)
    local level = checkNumber( dojo.level)
    return GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id118) and star == limitStar and level == limitLv
end

---是否能升阶强化
---@param dojo EquipDojo
---@return boolean 是否能升阶
function EquipUtils.IsCanLadderRiseUpgrade(dojo)
    local star = checkNumber(dojo.star)
    ---6星-11星
    local conditions =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.Scope)
    local limitStarLow, limitStarUp = SafeUnpack(conditions)
    return GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id118) and star >= limitStarLow and star < limitStarUp
end

---获取升星消耗
function EquipUtils.GetReforgeConsume()
    local idList =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.ReforgeConsumeId)
    local numList =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.ReforgeConsumeNum)
    local t = {}
    for index, value in ipairs(idList) do
        table.insert(t, {goodsId = value, num = numList[index] or 0})
    end
    return t
