---@param dojo EquipDojo
---@return {attrId:number, lowNum:number, upNum:number}[]
function EquipUtils.PreviewLadderRiseAttrs(dojo)
    local equipVo = cardConfMgr:GetEquipVoById(dojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local ladderRiseAttrs = mainEquipAttrVo.ladderRiseAttrs

    local t = {
        CardProgressionConstants.LadderRiseParams.FirstAttrNumScope,
        CardProgressionConstants.LadderRiseParams.SecondAttrNumScope
    }

    local result = {}
    for index, value in ipairs(ladderRiseAttrs) do
        local attrId, maxNum = SafeUnpack(value)
        local scopeId = t[index]
        local scope = EquipUtils.GetLadderRiseParamValue(scopeId)
        local up, low = SafeUnpack(scope)

        local lowNum = low * maxNum
        local upNum = up * maxNum
        ---@type BasicAttrAdditionVo
        local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrId)
        table.insert(result, {
            attrId = attrId,
            lowNum = attribute_format(attrAdditionVo.isConversion, lowNum),
            upNum  = attribute_format(attrAdditionVo.isConversion, upNum),
        })
    end
    
    return result
end

---@param id CardProgressionConstants.LadderRiseParams
