---获取装备副属性
---@param equipDojo EquipDojo
---@param index     integer   副属性序号
---@return table
---{
--- name string 属性名称
--- attrNum string 显示属性
--- attrNum integer 属性品质
---}
function EquipUtils.GetSubAttrByIndex(equipDojo, index)
    local idKey = string.format("attr%sId", index)
    local attrAdditionId = checkNumber(equipDojo[idKey])
    local numKey = string.format("attr%sNum", index)
    local attrNum = equipDojo[numKey]
    local qKay = string.format("attr%sQuality", index)
    local attrQuality = checkInt(equipDojo[qKay])
    ---@type BasicAttrAdditionVo
    local attrAdditionVo = cardConfMgr:GetBasicAttrAdditionById(attrAdditionId)
    local result = {
        name = attrAdditionVo.attrAdditionName,
        attrNum = attribute_format(attrAdditionVo.isConversion, attrNum),
        attrQuality = attrQuality
    }
    return result
