---获取装备主属性稀有度
---@param equipDojo EquipDojo
function EquipUtils.GetEquipmentMainAttrQuality(equipDojo)
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local mainAttrQualityVo = CfUtils.GetCf(AutoIds.IdSetting6057, "EquipmentMainAttrQualityVo", true) or {}
    local attrNum = mainEquipAttrVo.attrNum[tostring(goodsVo.quality)]
    local range = attrNum.baseMax - attrNum.baseMin
    local deltaValue = tonumber(equipDojo.mainAttrInit) - tonumber(attrNum.baseMin)
    local per = deltaValue / range
    for i, v in ipairs(mainAttrQualityVo) do
        if per < tonumber(v.point) then
            return v.qualityLv
        end
    end
    return mainAttrQualityVo[#mainAttrQualityVo].qualityLv
end

---计算装备主属性
---@param equipDojo EquipDojo
---@param isFormat? boolean
function EquipUtils.CalculateEquipmentMainAttr(equipDojo, isFormat)
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local grows = mainEquipAttrVo.grows
    local mainAttrInit = equipDojo.mainAttrInit
    local value = mainAttrInit

    local star = checkInt(equipDojo.star)
    local startStar =  EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar)
    local normalStar = math.min(star, startStar - 1)
    for i = 0, normalStar - 1 do
        --- 计算每一星下 每一级的属性 5 -> 当前星最大等级
        value = value + mainAttrInit * (grows[tostring(i)].growPre * 5)
    end

    value = value + mainAttrInit * (grows[tostring(normalStar)].growPre * checkInt(equipDojo.level))

    while star > startStar do
        startStar = startStar + 1
        value = value + EquipUtils.CalculateEquipmentLadderRiseMainAttr(equipDojo, startStar)
    end
    

    if isFormat then
        value = attribute_format(attrAddVo.isConversion, value)
    end
    return value
end

---计算装备升阶后的主属性
---@param equipDojo EquipDojo
function EquipUtils.CalculateEquipmentLadderRiseMainAttr(equipDojo, customStar)
    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local grows = mainEquipAttrVo.grows
    local stars = mainEquipAttrVo.stars
    local starsCount = stars.Count
    local mainAttrInit = equipDojo.mainAttrInit

    local curStar = checkNumber(equipDojo.star)
    local star_ = customStar or checkNumber(equipDojo.star)

    local value = 0
    local startStar
    local grow
    for i = starsCount - 1, 0, -1 do
        local star = stars[i]
        if star_ >= star then
            grow = grows[tostring(star)]
            break
        end
    end

    if grow then
        value = mainAttrInit * grow.growPre
        
    end

    return value
end

---通过品质更改副属性背景颜色
function EquipUtils.SwitchSubAttrColorByQuality(go, quality)
    local comp = go.transform:GetComponent(typeof(CS.UnityEngine.UI.Extensions.Gradient2))
    if isNull(comp) then return end
    
    local GradientColorKey = CS.UnityEngine.GradientColorKey
    local GradientAlphaKey = CS.UnityEngine.GradientAlphaKey
    local colorDefine = {
        {left = "#9c9c9c", right = "#d6d6d6"},
        {left = "#92af71", right = "#d0e5bd"},
        {left = "#6e91cd", right = "#bce2ff"},
        {left = "#b074c1", right = "#ecceff"},
        {left = "#ffa252", right = "#f9f0c2"},
        {left = "#cd6661", right = "#f3c2c1"},
    }
    
    local colorKeys = {}
    table.insert(colorKeys, GradientColorKey(XLuaUtils.HexToColor(colorDefine[checkInt(quality)].left), 0))
    table.insert(colorKeys, GradientColorKey(XLuaUtils.HexToColor(colorDefine[checkInt(quality)].right), 1))   
    local alphaKeys = {GradientAlphaKey(179 / 255, 0), GradientAlphaKey(255 / 255, 1)}
    comp.EffectGradient:SetKeys(colorKeys, alphaKeys)
end

---获取副属性百分比
---@param equipmentId integer 装备id
---@param attrId integer 副属性id
---@param value number 副属性数值
---@return number 
function EquipUtils.GetSubAttrPercent(equipmentId, attrId, value)
    local equipVo = cardConfMgr:GetEquipVoById(equipmentId)
    local subAttrProbVo = CfUtils.GetCf(AutoIds.IdSetting6041, "EquipmentSubAttrProbVo", true)
    local minV = nil
    local maxV = nil
    for i, v in pairs(subAttrProbVo) do
        if checkInt(v.purifyid) == checkInt(equipVo.poolSub) and checkInt(v.attTypeId) == checkInt(attrId) then
            if minV then
                if tonumber(v.starterdown) < minV then
                    minV = tonumber(v.starterdown)
                end
            else
                minV = tonumber(v.starterdown)
            end
            if maxV then
                if tonumber(v.starterup) > maxV then
                    maxV = tonumber(v.starterup)
                end
            else
                maxV = tonumber(v.starterup)
            end
        end
    end
    if not minV or not maxV then return end
    
    local range = maxV - minV
    local deltaV = value - minV
    local per = deltaV / range
    return per
end

---GenerateCustomEquip
---生成定制装备
---@param goodsId number 47定制装备表 id
---@return EquipDojo
function EquipUtils.GenerateCustomEquip(goodsId)
    ---@type GoodsCommissionVo
    local commissionVo      = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    local equipId           = commissionVo.effectId
    local attrConfId        = commissionVo.effectNum
    ---@type EquipCustomAttrVo
    local equipCustomAttrVo = CardConfMgr:GetInstance():GetEquipCustomAttrVo(attrConfId)
    local EquipDojo = import('Game.Dojo.EquipDojo')
    ---@type EquipDojo
    local equipDojo = EquipDojo.New()

    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(equipId)
    local mainInitMax, attrMainId, poolMain = EquipUtils.GetMainAttrInitMaxByVo(equipVo)
    local level = equipCustomAttrVo.level
    local star = equipCustomAttrVo.star
    equipDojo.equipmentId  = equipId
    equipDojo.star         = star
    equipDojo.level        = level
    equipDojo.mainAttrId   = equipCustomAttrVo.mainAttribute == 0 and attrMainId or equipCustomAttrVo.mainAttribute
    equipDojo.mainAttrType = poolMain
    equipDojo.mainAttrInit = equipCustomAttrVo.mainAttrInit == 0 and checkNumber(mainInitMax) or equipCustomAttrVo.mainAttrInit
    equipDojo.mainAttrNum  = EquipUtils.CalculateEquipmentMainAttr(equipDojo, false)

    local poolSub = equipVo.poolSub
    local attributes = equipCustomAttrVo:GetSubAttributes()
    local SafeUnpack = SafeUnpack
    for i = 1, star do
        local attribute     = attributes[i]
        if attribute then
            local attrId, attrV = SafeUnpack(attribute)
            local quality       = EquipUtils.GetSubAttrQuality(poolSub, attrId, attrV)
            equipDojo[string.format("attr%sId", i)] = attrId
            equipDojo[string.format("attr%sNum", i)] = attrV
            equipDojo[string.format("attr%sQuality", i)] = quality
            equipDojo[string.format("attr%sType", i)] = poolSub
        end

    end

    return equipDojo

end

---GenerateCustomEquip
---生成定制装备
---@param goodsId number 40定制装备表 id
---@return EquipDojo
function EquipUtils.GenerateEquip(goodsId)
    local EquipDojo = import('Game.Dojo.EquipDojo')
    ---@type EquipDojo
    local equipDojo = EquipDojo.New()
    equipDojo.equipmentId  = goodsId
    equipDojo.star         = 0
    equipDojo.level        = 1

    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(goodsId)
    local mainInitMax, attrMainId, poolMain = EquipUtils.GetMainAttrInitMaxByVo(equipVo)
    equipDojo.mainAttrId   = attrMainId
    equipDojo.mainAttrType = poolMain
    equipDojo.mainAttrInit = mainInitMax
    equipDojo.mainAttrNum  = EquipUtils.CalculateEquipmentMainAttr(equipDojo, false)

    return equipDojo
end

---GetMainAttrInitMax
---获取主属性初始最大值
---@param equipVo EquipVo
function EquipUtils.GetMainAttrInitMaxByVo(equipVo)
    local rare = equipVo.rare
    local poolMain = equipVo.poolMain
    ---@type EquipAttrVo
    local equipAttrVo = cardConfMgr:GetEquipAttrVoById(poolMain)
    local attrConf = equipAttrVo.attrNum[tostring(rare)]
    local num = attrConf and attrConf.baseMax or 0
    local attrId = equipAttrVo.attrAdditionId
    return num, attrId, poolMain

end


---获取副属性百分比
---@param poolSub number 装备副属性池类型
---@param attrId integer 副属性id
---@param value number 副属性数值
---@return number 
function EquipUtils.GetSubAttrQuality(poolSub, attrId, value)
    ---@type EquipmentSubAttrProbVo
    local subAttrProbVo = CfUtils.GetCf(AutoIds.IdSetting6041, "EquipmentSubAttrProbVo", true)
    local quality       = 1
    local flag           = nil
    local checkInt      = checkInt
    local tonumber      = tonumber
    value               = checkNumber(value)
    for i, v in pairs(subAttrProbVo) do
        if checkInt(v.purifyid) == poolSub and checkInt(v.attTypeId) == checkInt(attrId) then
            flag = true
            local max = tonumber(v.starterup)
            local min = tonumber(v.starterdown)
            if value >= min then
                quality = v.quality
            end

            if value < max then
                break
            end

        elseif flag then
            break
        end
    end
    return quality
end

---判断装备是否可以刻印
---@param equipDojo EquipDojo
---@return boolean
function EquipUtils.CanEngrave(equipDojo)
    -- 刻印过的装备不可以再次刻印
    if checkInt(equipDojo.bindPlayerCardId) > 0 then
        return false
    end

    local qualityLimit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveQuality))
    local levelLimit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveLevel))
    local starLimit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveStar))
    -- local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    return EquipUtils.GetQuality(equipDojo) >= qualityLimit and checkInt(equipDojo.star) >= starLimit and checkInt(equipDojo.level) >= levelLimit
end

---计算装备刻印属性加成
---@param equipDojo EquipDojo
---@param isFormat boolean 是否格式化
function EquipUtils.CalculateEquipmentEngraveAttr(equipDojo, isFormat)
    if checkInt(equipDojo.bindPlayerCardId) == 0 then return end

    local equipVo = cardConfMgr:GetEquipVoById(equipDojo.equipmentId)
    local mainEquipAttrVo = cardConfMgr:GetEquipAttrVoById(equipVo.poolMain)
    local attrAddVo = cardConfMgr:GetBasicAttrAdditionById(mainEquipAttrVo.attrAdditionId)
    local mainAttr = EquipUtils.CalculateEquipmentMainAttr(equipDojo, false)
    local addition = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveAddiRate))
    local value = mainAttr * addition

    if isFormat then
        value = attribute_format(attrAddVo.isConversion, value)
    end
    return value
end

---刻印是否生效
---@param equipDojo EquipDojo
function EquipUtils.IsEngraveActive(equipDojo)
    local bindPlayerCardId = checkInt(equipDojo.bindPlayerCardId)
    if bindPlayerCardId == 0 then return false end
    
    local playerCardId = checkInt(equipDojo.playerCardId)
    return bindPlayerCardId == playerCardId 
end

---获取刻印消耗
function EquipUtils.GetEngraveConsume()
    local goodsIds = parse_strings(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveGoodsId), ";")
    local goodsNums = parse_strings(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentEngraveGoodsNum), ";")
    local tmp = {}
    for i, v in ipairs(goodsIds) do
        table.insert(tmp, {goodsId = v, goodsNum = goodsNums[i]})
    end
    return tmp
end

---获取刻印金币消耗
function EquipUtils.GetEngraveConsumeGold()
    local consume = EquipUtils.GetEngraveConsume()
    for i, v in ipairs(consume) do
        if checkInt(v.goodsId) == Constants.Currency.GoldId then
            return {v}
        end
    end
    return {}
end

---获取刻印材料消耗
function EquipUtils.GetEngraveConsumeMaterial()
    local consume = EquipUtils.GetEngraveConsume()
    for i, v in ipairs(consume) do
        if checkInt(v.goodsId) == Constants.Currency.GoldId then
            table.remove(consume, i)
            break
        end
    end
    return consume
end

---计算装备快速升级消耗
---@return boolean, table, number, number @ 是否可以升级, 消耗, 星级, 等级
function EquipUtils.CalculateQuickUpgradeConsume(equipDojo)
    local canUpgrade = true
    local upgradeTimes = 0
    local consume = {}
    local star = nil
    local level = nil
    while canUpgrade do
        local newStar, newLevel
        canUpgrade, consume, newStar, newLevel = EquipUtils.GetUpgradeConsume(equipDojo, consume, upgradeTimes)
        if canUpgrade then
            upgradeTimes = upgradeTimes + 1
            star = newStar
            level = newLevel
        end
    end
    return upgradeTimes > 0, consume, star, level 
end

---获取装备升级消耗
function EquipUtils.GetUpgradeConsume(equipDojo, consume, upgradeTimes)
    local totalConsume = clone(consume)
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(equipDojo.equipmentId)
    local levelLimit = CardProgressionConstants.EquipmentLevelUpperLimit
    local starLimit = EquipUtils.GetEquipmentStarMaxByEquipmentId(equipDojo.equipmentId)
    local star = checkInt(equipDojo.star)
    local level = checkInt(equipDojo.level) + upgradeTimes + 1
    if level > levelLimit then
        star = math.floor(level / (levelLimit + 1)) + star
        if star > starLimit then -- 满星满级不能继续提升
            return false, consume
        end
        level = level % (levelLimit + 1)
    end
    local params = {
        quality = goodsVo.quality,
        star    = star,
        level   = level
    }
    local equipmentCNRVo = EquipUtils.GetEquipmentCNRVo(params)
    local upgradeConsume = nil
    if level == 0 then
        upgradeConsume = parse_rewards(equipmentCNRVo.upstarItem, equipmentCNRVo.upstarNum)
    else
        upgradeConsume = parse_rewards(equipmentCNRVo.upgradeItem, equipmentCNRVo.upgradeNum)
    end
    for _, v in ipairs(upgradeConsume) do
        local isFind = false
        for _, v2 in ipairs(totalConsume) do
            if checkInt(v2.goodsId) == checkInt(v.goodsId) then
                isFind = true
                v2.goodsNum = checkInt(v2.goodsNum) + checkInt(v.goodsNum)
            end
        end
        if not isFind then
            table.insert(totalConsume, v)
        end
    end
    local _, errorTip = GoodsUtils.CheckGoodConsume(totalConsume)
    if errorTip then
        return false, consume
    else
        return true, totalConsume, star, level
    end
end

---判断装备预设是否达到上限
function EquipUtils.CheckEquipmentPresetLimit()
    local PlayerComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local equipmentDiySuits = checkTable(PlayerComponent.playerDojo.equipmentDiySuits)
    local limit = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.EquipmentPresetUpperLimit))
    return #equipmentDiySuits >= limit
end


